#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define LINE_MAX   0x800
#define FIELD_MAX  0x100

static char main_line[LINE_MAX];
static char main_key[FIELD_MAX];
static char main_val[FIELD_MAX];

static void decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, j = 0;
    while (i < len) {
        char c = src[i];
        if (c == '+') {
            dst[j++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i+1]) &&
                   isxdigit((unsigned char)src[i+2])) {
            char hi = src[i+1];
            char lo = src[i+2];
            hi = (char)tolower((unsigned char)hi);
            lo = (char)tolower((unsigned char)lo);
            unsigned int value = (hi >= 'a' ? hi - 'a' + 10 : hi - '0') << 4;
            value += (lo >= 'a' ? lo - 'a' + 10 : lo - '0');
            dst[j++] = (char)value;
            i += 3;
        } else {
            dst[j++] = c;
            ++i;
        }
    }
    dst[j] = '\0';
}

int main(void)
{
    if (fgets(main_line, sizeof(main_line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }
    size_t line_len = strlen(main_line);
    while (line_len > 0 && (main_line[line_len-1] == '\n' || main_line[line_len-1] == '\r')) {
        main_line[--line_len] = '\0';
    }
    size_t pos = 0;
    while (pos < line_len) {
        size_t key_start = pos;
        while (pos < line_len && main_line[pos] != '=' && main_line[pos] != '&')
            ++pos;
        size_t key_len = pos - key_start;
        decode(main_line + key_start, key_len, main_key);
        if (pos < line_len && main_line[pos] == '=') {
            ++pos;
            size_t val_start = pos;
            while (pos < line_len && main_line[pos] != '&')
                ++pos;
            size_t val_len = pos - val_start;
            decode(main_line + val_start, val_len, main_val);
        } else {
            main_val[0] = '\0';
        }
        printf("%s=%s\n", main_key, main_val);
        if (pos < line_len && main_line[pos] == '&')
            ++pos;
    }
    return 0;
}
